//! Known-answer transcripts of every instantiation, against the reference implementation.
//!
//! # Overview
//!
//! Each file under known_answers records one key's life, generated by the reference from a seed.
//!
//! ```text
//! seed               the bytes whose SHAKE128 stream feeds key generation
//! activation         the requested first epoch and epoch count
//! expanded           the activation widened to whole bottom trees
//! public_key         the encoded public key
//! secret_key_sha256  the digest of the encoded secret key
//! sign               epoch, message, digest and length of the signature
//! signature          the first signature in full
//! advance            the prepared window after sliding, and the new secret key digest
//! ```
//!
//! The plan is the same for every instantiation, with c epochs per bottom tree:
//! activate trees 1 to 3, sign at c, 2c - 1, 2c and 3c - 1, slide, then sign at 3c and 4c - 1.
//! Those are the first and last epochs of each tree, and the slide crosses the window's edge.

use std::{fs, path::Path, str::Lines};

use axiom_hashsig::{
    ChunkSize, HypercubeLifetime, Instantiation, LeafEpoch, SecretKey, SeedStream, Signature,
    Target, TargetSumLifetime, VerifyError,
};
use sha2::{Digest, Sha256};

/// Decodes hex without a prefix.
fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digit"))
        .collect()
}

/// The SHA-256 digest of some bytes.
fn sha256(bytes: &[u8]) -> Vec<u8> {
    Sha256::digest(bytes).to_vec()
}

/// The instantiation a transcript file names.
fn instantiation(name: &str) -> Instantiation {
    let lifetime = match &name[..11] {
        "lifetime-18" => TargetSumLifetime::Epochs18,
        "lifetime-20" => TargetSumLifetime::Epochs20,
        "lifetime-32" => return Instantiation::Hypercube(HypercubeLifetime::Epochs32),
        "lifetime-8-" => return Instantiation::Hypercube(HypercubeLifetime::TestOnly8),
        other => panic!("unknown lifetime {other}"),
    };
    let chunk = match &name[12..14] {
        "w1" => ChunkSize::One,
        "w2" => ChunkSize::Two,
        "w4" => ChunkSize::Four,
        "w8" => ChunkSize::Eight,
        other => panic!("unknown chunk {other}"),
    };
    let target = match &name[15..] {
        "expected" => Target::Expected,
        "offset10" => Target::TenPercentAbove,
        other => panic!("unknown target {other}"),
    };
    Instantiation::TargetSum {
        lifetime,
        chunk,
        target,
    }
}

/// The value of a key = value line with the expected key.
fn field<'a>(line: &'a str, key: &str) -> &'a str {
    line.strip_prefix(key)
        .and_then(|rest| rest.strip_prefix(" = "))
        .unwrap_or_else(|| panic!("expected {key}, found {line}"))
}

/// Checks a signature's negative cases: another epoch, another message, and a flipped byte.
fn assert_rejections(sk: &SecretKey, epoch: u32, message: &[u8; 32], signature: &Signature) {
    let scheme = sk.scheme();
    let public = sk.public_key();

    // Another epoch encodes the message differently, or leads elsewhere in the tree.
    assert!(
        scheme
            .verify(&public, LeafEpoch(epoch ^ 1), message, signature)
            .is_err()
    );

    // Another message, one bit apart.
    let mut other = *message;
    other[0] ^= 1;
    assert!(
        scheme
            .verify(&public, LeafEpoch(epoch), &other, signature)
            .is_err()
    );

    // The last chain value with its lowest bit flipped decodes, and then fails at the root.
    let mut bytes = signature.to_bytes();
    let last = bytes.len() - 4;
    bytes[last] ^= 1;
    if let Ok(tampered) = scheme.decode_signature(&bytes) {
        assert_eq!(
            scheme.verify(&public, LeafEpoch(epoch), message, &tampered),
            Err(VerifyError::RootMismatch)
        );
    }
}

/// Parses a space-separated list of integers.
fn numbers(text: &str) -> Vec<u64> {
    text.split(' ')
        .map(|n| n.parse().expect("an integer"))
        .collect()
}

/// The value of the next line, which must carry the expected key.
fn next<'a>(lines: &mut Lines<'a>, key: &str) -> &'a str {
    field(lines.next().expect("a complete transcript"), key)
}

/// Replays one transcript and returns the number of signatures and slides checked.
fn replay(path: &Path) -> (usize, usize) {
    let name = path
        .file_stem()
        .and_then(|stem| stem.to_str())
        .expect("a UTF-8 file name");
    let text = fs::read_to_string(path).expect("a readable transcript");
    let mut lines = text.lines();
    assert_eq!(lines.next(), Some(format!("[{name}]").as_str()));
    let scheme = instantiation(name).scheme();

    // Key generation from the seeded stream.
    let seed = hex(next(&mut lines, "seed"));
    let activation = numbers(next(&mut lines, "activation"));
    let expanded = numbers(next(&mut lines, "expanded"));
    let (public, mut secret) = scheme
        .generate(
            &mut SeedStream::new(&seed),
            activation[0]..activation[0] + activation[1],
        )
        .expect("an activation inside the lifetime");
    assert_eq!(secret.activation(), expanded[0]..expanded[1], "{name}");
    assert_eq!(
        public.to_bytes(),
        hex(next(&mut lines, "public_key")),
        "{name}"
    );
    assert_eq!(public.to_bytes().len(), scheme.public_key_len());
    assert_eq!(
        sha256(&secret.to_bytes()),
        hex(next(&mut lines, "secret_key_sha256")),
        "{name}"
    );
    assert_eq!(scheme.decode_public_key(&public.to_bytes()), Ok(public));
    assert_eq!(
        scheme.decode_secret_key(&secret.to_bytes()).as_ref(),
        Ok(&secret)
    );

    let (mut signatures, mut slides) = (0, 0);
    while let Some(line) = lines.next() {
        if let Some(rest) = line.strip_prefix("advance = ") {
            let (window, digest) = rest.rsplit_once(' ').expect("a window and a digest");
            let window = numbers(window);
            assert!(secret.advance(), "{name}: the window cannot slide");
            assert_eq!(secret.prepared(), window[0]..window[1], "{name}");
            assert_eq!(
                sha256(&secret.to_bytes()),
                hex(digest),
                "{name}: key after slide"
            );
            slides += 1;
            continue;
        }
        let parts: Vec<&str> = field(line, "sign").split(' ').collect();
        let epoch: u32 = parts[0].parse().expect("an epoch");
        let message: [u8; 32] = hex(parts[1]).try_into().expect("a 32-byte message");
        let signature = secret
            .sign(LeafEpoch(epoch), &message)
            .expect("an epoch of the prepared window");
        let bytes = signature.to_bytes();
        assert_eq!(
            sha256(&bytes),
            hex(parts[2]),
            "{name}: signature at epoch {epoch}"
        );
        assert_eq!(bytes.len().to_string(), parts[3]);
        assert_eq!(bytes.len(), scheme.signature_len());
        assert_eq!(
            scheme.verify(&public, LeafEpoch(epoch), &message, &signature),
            Ok(())
        );
        assert_rejections(&secret, epoch, &message, &signature);

        // The first signature is stored whole: it decodes to ours.
        if signatures == 0 {
            let reference = hex(next(&mut lines, "signature"));
            assert_eq!(scheme.decode_signature(&reference), Ok(signature));
        }
        signatures += 1;
    }
    (signatures, slides)
}

#[test]
fn every_instantiation_matches_the_reference() {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/known_answers");
    let mut files: Vec<_> = fs::read_dir(&directory)
        .expect("the transcript directory")
        .map(|entry| entry.expect("a directory entry").path())
        .collect();
    files.sort();

    // One file per instantiation, each with six signatures and one slide.
    assert_eq!(files.len(), Instantiation::ALL.len());
    for path in &files {
        assert_eq!(replay(path), (6, 1), "{}", path.display());
    }
}
